def get_img(key: str) -> Image.Image:
    """Return embedded PIL image for key, or gray placeholder."""
    b64 = _IMAGES_B64.get(key, "")
    if b64:
        return Image.open(io.BytesIO(base64.b64decode(b64))).convert("RGB")
    img = Image.new("RGB", (400, 280), (70, 70, 70))
    draw = ImageDraw.Draw(img)
    draw.text((20, 120), f"Image: {key}", fill=(200, 200, 200))
    return img


