# TRAINING FUNCTIONS
# ══════════════════════════════════════════════════════════
def build_generators():
    train_gen = ImageDataGenerator(
        rescale=1./255, rotation_range=30, width_shift_range=0.2,
        height_shift_range=0.2, shear_range=0.2, zoom_range=0.2,
        horizontal_flip=True, fill_mode="nearest", validation_split=0.2,
    ).flow_from_directory(
        DATASET_DIR, target_size=IMG_SIZE, batch_size=BATCH_SIZE,
        class_mode="categorical", subset="training", shuffle=True)
    val_gen = ImageDataGenerator(rescale=1./255, validation_split=0.2,
    ).flow_from_directory(
        DATASET_DIR, target_size=IMG_SIZE, batch_size=BATCH_SIZE,
        class_mode="categorical", subset="validation", shuffle=False)
    return train_gen, val_gen

def build_model(num_classes):
    base = MobileNetV2(input_shape=(*IMG_SIZE,3), include_top=False, weights="imagenet")
    base.trainable = False
    model = models.Sequential([
        base, layers.GlobalAveragePooling2D(), layers.BatchNormalization(),
        layers.Dense(256, activation="relu"), layers.Dropout(0.4),
        layers.Dense(128, activation="relu"), layers.Dropout(0.3),
        layers.Dense(num_classes, activation="softmax"),
    ])
    model.compile(optimizer=tf.keras.optimizers.Adam(1e-3),
                  loss="categorical_crossentropy", metrics=["accuracy"])
    return model

def train_model():
    Path("models").mkdir(exist_ok=True)
    train_gen, val_gen = build_generators()
    class_names = list(train_gen.class_indices.keys())
    np.save(LABELS_PATH, class_names)
    model = build_model(len(class_names))
    cb = [
        callbacks.EarlyStopping(patience=5, restore_best_weights=True, verbose=1),
        callbacks.ReduceLROnPlateau(factor=0.5, patience=3, verbose=1),
        callbacks.ModelCheckpoint(MODEL_PATH, save_best_only=True, verbose=1),
    ]
    model.fit(train_gen, validation_data=val_gen, epochs=EPOCHS, callbacks=cb)
    for layer in model.layers[0].layers[-20:]:
        layer.trainable = True
    model.compile(optimizer=tf.keras.optimizers.Adam(1e-5),
                  loss="categorical_crossentropy", metrics=["accuracy"])
    model.fit(train_gen, validation_data=val_gen, epochs=5, callbacks=cb)
    print(f"✅  Model saved → {MODEL_PATH}")

def load_model_and_labels():
    if not Path(MODEL_PATH).exists():
        return None, None
    return tf.keras.models.load_model(MODEL_PATH), list(np.load(LABELS_PATH, allow_pickle=True))

# ══════════════════════════════════════════════════════════
# PREDICTION
# ══════════════════════════════════════════════════════════
def predict(image, model, class_names):
    if image is None:
        return "❌ No image uploaded.", "", "", "", None
    if model is None:
        msg = (
            "### ⚠️ Detection Disabled — No Model Loaded\n\n"
            "The image detection feature requires a trained model.\n\n"
            "**To enable detection:**\n"
            f"- Place your trained model at `{MODEL_PATH}`\n"
            f"- Place class labels at `{LABELS_PATH}`\n"
            f"- OR put the PlantVillage dataset at `{DATASET_DIR}` and restart\n\n"
            "**Download dataset:** https://www.kaggle.com/datasets/abdallahalidev/plantvillage-dataset\n\n"
            "All other tabs (Weed Encyclopedia, Seasonal Guide, Gallery, etc.) work normally."
        )
        return "⚠️ No model loaded — Demo Mode", msg, "", "", get_img("healthy")
    arr   = np.expand_dims(np.array(image.resize(IMG_SIZE))/255.0, 0)
    preds = model.predict(arr, verbose=0)[0]
    top5  = preds.argsort()[-5:][::-1]
    label = class_names[top5[0]]
    conf  = preds[top5[0]]*100
    is_healthy = "healthy" in label.lower()
    info  = DISEASE_INFO.get("healthy" if is_healthy else label, DEFAULT_INFO)
    parts   = label.split("___")
    plant   = parts[0].replace("_"," ")
    disease = parts[1].replace("_"," ") if len(parts)>1 else "Unknown"
    title   = f"{info['emoji']}  {plant}  →  {disease}  ({conf:.1f}% confidence)"
    sev_icon= "🟢" if info["severity"]=="None" else ("🔴" if "HIGH" in info["severity"].upper() or "CRITICAL" in info["severity"].upper() else "🟡")
    details = (
        f"### 🌱 Diagnosis\n**Status:** {info['status']}\n\n"
        f"**Description:** {info['description']}\n\n"
        f"{sev_icon} **Severity:** {info['severity']}\n\n---\n"
        f"### 💊 Treatment\n{info['treatment']}\n\n---\n"
        f"### 🛡️ Prevention\n{info.get('prevention','• Practice good field hygiene')}\n\n---\n"
        f"### 🌿 Organic Options\n{info.get('organic','• Neem oil spray')}"
    )
    top5_text = "### 🔢 Top-5 Predictions\n\n"
    for idx in top5:
        lbl  = class_names[idx].replace("___"," → ").replace("_"," ")
        c    = preds[idx]*100
        bar  = "█"*int(c/4) + "░"*(25-int(c/4))
        top5_text += f"`{bar}` **{c:5.1f}%** — {lbl}\n\n"
    advice = ("✅ Your plant is healthy! Keep up the good care!" if is_healthy else
              "🚨 **Urgent!** Act immediately — this spreads fast." if ("CRITICAL" in info["severity"].upper() or "VERY HIGH" in info["severity"].upper()) else
              "⚠️ **Act Soon.** Start treatment within 1-2 days." if info["severity"]=="High" else
              "ℹ️ **Manageable.** Follow treatment steps and monitor weekly.")
    ref_img = get_img(info.get("img_key",""))
    return title, details, top5_text, advice, ref_img

