# MAIN
# ══════════════════════════════════════════════════════════
def main():
    print("\n╔═══════════════════════════════════════════════════════╗")
    print("║   🌿 PLANT DISEASE DETECTION SYSTEM — V2 ENHANCED    ║")
    print("╚═══════════════════════════════════════════════════════╝\n")

    model, class_names = None, []

    if Path(MODEL_PATH).exists() and Path(LABELS_PATH).exists():
        print("✅  Pre-trained model found. Skipping training.\n")
        model, class_names = load_model_and_labels()
        print(f"📋  {len(class_names)} disease classes loaded.")

    elif Path(DATASET_DIR).exists():
        print("📂  Dataset found. Starting training...\n")
        train_model()
        model, class_names = load_model_and_labels()
        print(f"📋  {len(class_names)} disease classes loaded.")

    else:
        print("⚠️  No model and no dataset found.")
        print("   Launching in DEMO MODE — all tabs work EXCEPT leaf detection.")
        print()
        print("   To enable leaf detection, either:")
        print(f"   1. Place trained model at:  {MODEL_PATH}")
        print(f"      and class labels at:      {LABELS_PATH}")
        print(f"   2. OR place PlantVillage dataset at: {DATASET_DIR}")
        print(f"      Download: https://www.kaggle.com/datasets/abdallahalidev/plantvillage-dataset")
        print()

    launch_app(model, class_names)

if __name__ == "__main__":
    main()

